{
  "selections": [
    {
      "trait_id": "/core_belief/young_schema",
      "background_ids": ["/childhood_data", "/situations/3"],
      "relevance": "상담사가 '부족하다는 느낌'을 언급하며 그 느낌이 오래 몸에 새겨져 있다고 말함. 결함/수치심 스키마가 이 느낌의 핵심이고, 어린 시절 결함을 감춰야 했던 경험과 밤에 실수 장면이 떠오를 때 몸이 무겁게 가라앉는 반응이 이를 뒷받침함."
    },
    {
      "trait_id": "/core_belief/schema_definition",
      "background_ids": ["/childhood_data"],
      "relevance": "상담사가 '부족하다는 느낌'을 꺼내자 몸이 먼저 긴장한다고 말한 것은, 근본적으로 결함이 있어 드러나면 사랑받지 못할 것이라는 느낌이 인지적 수준을 넘어 체화된 상태임을 보여줌. 어린 시절 있는 그대로의 모습이 결함으로 취급된 경험이 그 체화의 근원."
    },
    {
      "trait_id": "/intermediate_beliefs/attitude",
      "background_ids": ["/situations/3"],
      "relevance": "'눈에 안 띄어야 한다는 느낌'은 부족한 모습·진짜 감정을 들키는 것이 끔찍하다는 태도와 직접 연결됨. 내담자가 상상만 해도 몸이 긴장한다고 한 것은 이 태위가 얼마나 강하게 체화되어 있는지를 보여줌."
    },
    {
      "trait_id": "/intermediate_beliefs/rule",
      "background_ids": ["/situations/3"],
      "relevance": "'눈에 안 띄어야 한다는 느낌'은 괜찮은 모습만 보여야 한다는 규칙의 체화된 표현. 내담자가 '괜찮은 척이 당연한 것처럼 느껴진다'고 한 것이 이 규칙이 자동화된 상태임을 확인시켜줌."
    },
    {
      "trait_id": "/intermediate_beliefs/assumption_negative",
      "background_ids": ["/situations/1"],
      "relevance": "부족한 모습을 보이면 실망해서 떠날 것이라는 가정은, 내담자가 '실망해서 떠나는 건 아닐까'라고 자동적으로 반응한 근거. 상담사가 그 아래를 상상해 보자고 했을 때 몸이 긴장한 것은 이 가정이 불러오는 위협감을 체감한 것."
    },
    {
      "trait_id": "/coping_strategies/1",
      "background_ids": ["/situations/3"],
      "relevance": "'눈에 안 띄어야 한다'는 느낌은 밝고 괜찮은 모습만 유지하며 힘든 감정을 혼자 삭이는 전략의 내면 표현. 내담자가 다음 날 괜찮은 척한다고 한 것이 이 전략의 실제 작동 사례."
    }
  ]
}

